* { box-sizing: border-box; }
body {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  margin: 0; background: #f4f5f7; color: #1a1a1a;
}
.topbar { background: #fff; border-bottom: 1px solid #e5e7eb; padding: 16px 20px; }
.topbar h1 { font-size: 20px; margin: 0; max-width: 900px; margin: 0 auto; }
.wrap { max-width: 900px; margin: 0 auto; padding: 24px 20px 100px; }

/* Save bar */
.savebox { display: flex; gap: 8px; background: #fff; padding: 12px;
  border: 1px solid #e5e7eb; border-radius: 12px; margin-bottom: 10px; }
.savebox input { flex: 1; border: 1px solid #d1d5db; border-radius: 8px;
  padding: 10px 12px; font-size: 15px; }
.savebox input.bad { border-color: #ef4444; background: #fef2f2; }
.savebox button { border: 0; background: #2563eb; color: #fff; font-size: 15px;
  padding: 10px 18px; border-radius: 8px; cursor: pointer; font-weight: 600; }
.savebox button:hover { background: #1d4ed8; }
.savebox button:disabled { opacity: .6; cursor: default; }

.inline-err { color: #b91c1c; font-size: 13px; margin: 0 0 12px; min-height: 0; }
.inline-err:empty { margin: 0; }
.notice { background: #fffbeb; border: 1px solid #fde68a; color: #92400e;
  border-radius: 10px; padding: 10px 12px; font-size: 13.5px; margin: 0 0 14px; }
.notice a { color: #92400e; font-weight: 700; cursor: pointer;
  text-decoration: underline; margin-left: 6px; }

/* Search */
.searchbar { position: relative; margin: 6px 0 20px; }
.searchbar input { width: 100%; border: 1px solid #d1d5db; border-radius: 10px;
  padding: 12px 14px 12px 40px; font-size: 15px; background: #fff; }
.searchbar .icon { position: absolute; left: 14px; top: 50%;
  transform: translateY(-50%); color: #9ca3af; font-size: 15px; }

/* Layout */
.layout { display: grid; grid-template-columns: 190px 1fr; gap: 24px; }
@media (max-width: 640px) { .layout { grid-template-columns: 1fr; } }
.side h2 { font-size: 12px; text-transform: uppercase; letter-spacing: .04em;
  color: #9ca3af; margin: 0 0 8px; }
.tags { display: flex; flex-wrap: wrap; gap: 6px; }
.tag { display: inline-block; padding: 5px 11px; border-radius: 20px; cursor: pointer;
  font-size: 13px; background: #eef2ff; color: #4338ca; border: 1px solid #dbe1ff; }
.tag:hover { background: #e0e7ff; }
.tag.active { background: #4338ca; color: #fff; border-color: #4338ca; }
.tag .num { opacity: .65; margin-left: 4px; font-size: 12px; }

.count { color: #6b7280; font-size: 13px; margin: 0 0 10px; }
.list { list-style: none; padding: 0; margin: 0; }
.item { background: #fff; border: 1px solid #e5e7eb; border-radius: 12px;
  padding: 13px 15px; margin-bottom: 10px; display: flex; align-items: flex-start; gap: 12px; }
.item.fresh { border-color: #93c5fd; box-shadow: 0 0 0 3px #dbeafe; }
.item.flash { border-color: #fbbf24; box-shadow: 0 0 0 3px #fef3c7; }
.favicon { width: 32px; height: 32px; border-radius: 8px; background: #eef2ff;
  display: flex; align-items: center; justify-content: center; font-size: 15px;
  color: #4f46e5; font-weight: 700; flex-shrink: 0; }
.meta { min-width: 0; flex: 1; }
.title { font-size: 15px; font-weight: 600; margin: 0 0 2px; display: flex;
  align-items: center; gap: 8px; flex-wrap: wrap; }
.title a { color: #111827; text-decoration: none; }
.title a:hover { text-decoration: underline; }
.title mark { background: #fde68a; padding: 0 1px; border-radius: 2px; }
.warn { font-size: 11px; font-weight: 600; color: #92400e; background: #fef3c7;
  border: 1px solid #fde68a; padding: 1px 7px; border-radius: 20px; }
.link-btn { font-size: 12px; color: #2563eb; text-decoration: none; font-weight: 500;
  cursor: pointer; background: none; border: 0; padding: 0; }
.link-btn:hover { text-decoration: underline; }
.url { font-size: 12.5px; color: #6b7280; margin: 0 0 6px; white-space: nowrap;
  overflow: hidden; text-overflow: ellipsis; }
.url mark { background: #fde68a; padding: 0 1px; border-radius: 2px; }

/* Tag chips + prompt */
.chips { display: flex; flex-wrap: wrap; gap: 6px; align-items: center; position: relative; }
.chip { background: #eef2ff; color: #4338ca; border: 1px solid #dbe1ff; border-radius: 20px;
  font-size: 12.5px; padding: 2px 8px; display: inline-flex; gap: 5px; align-items: center; cursor: pointer; }
.chip .x { color: #818cf8; font-weight: 700; cursor: pointer; }
.prompt { font-size: 12px; color: #2563eb; margin: 0 0 6px; font-weight: 600; }
.taginput { border: 1px solid #93c5fd; border-radius: 20px; font-size: 12.5px;
  padding: 4px 12px; outline: 0; width: 160px; }
.skip { background: none; border: 0; color: #9ca3af; font-size: 12px; cursor: pointer;
  text-decoration: underline; }
.sugg { position: absolute; top: 100%; left: 0; background: #fff; border: 1px solid #e5e7eb;
  border-radius: 8px; margin-top: 4px; box-shadow: 0 6px 20px rgba(0,0,0,.08); z-index: 5;
  min-width: 160px; overflow: hidden; }
.sugg div { padding: 7px 12px; font-size: 13.5px; cursor: pointer; }
.sugg div:hover, .sugg div.hl { background: #eef2ff; }
.trash { border: 0; background: none; cursor: pointer; color: #9ca3af; font-size: 16px;
  padding: 6px 8px; border-radius: 8px; flex-shrink: 0; }
.trash:hover { background: #fef2f2; color: #dc2626; }

/* Empty states (SCN-005) */
.empty { text-align: center; padding: 56px 20px; color: #6b7280; }
.empty .big { font-size: 44px; margin-bottom: 12px; }
.empty h3 { font-size: 17px; color: #374151; margin: 0 0 6px; }
.empty p { font-size: 14px; margin: 0 0 4px; }
.empty .cta { font-size: 13px; color: #2563eb; margin-top: 10px; }

/* Undo toast (SCN-008) */
.toast { position: fixed; left: 50%; transform: translateX(-50%); bottom: 26px;
  background: #111827; color: #fff; padding: 12px 16px; border-radius: 12px; font-size: 14px;
  display: flex; align-items: center; gap: 14px; box-shadow: 0 8px 30px rgba(0,0,0,.25);
  overflow: hidden; max-width: 90vw; }
.toast span { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.toast button { background: none; border: 0; color: #93c5fd; font-weight: 700;
  cursor: pointer; font-size: 14px; flex-shrink: 0; }
.toast .timer { position: absolute; left: 0; bottom: 0; height: 3px; background: #3b82f6; }

